def compute(vars):
    shares_owned = vars["v1"]
    unvested_rsus = vars["v2"]
    total_shares = shares_owned + unvested_rsus

    return {
        "value": total_shares,
        "trace": {
            "shares_owned": shares_owned,
            "unvested_rsus": unvested_rsus,
            "total_shares": total_shares,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
